const POOLS: Array<[PoolId, string]> = [
  ["mixed", "Shop + drop"],
  ["shop", "Только Shop Item"],
  ["drop", "Только Random drop"],
];

type Entry = { name: string; tip: string; ret: number; prot: number };

const TALENTS: Entry[] = [{"name": "Divine Hammer", "tip": "Blessed Hammer now lasts for 3 additional seconds and has 50% increased range for its damage.", "ret": 189.7, "prot": 183.5}, {"name": "Divine Toll", "tip": "Casting Blessed Hammer has 25% chance to spawn an additional hammer after a 0,5 second delay.", "ret": 182.3, "prot": 176.1}, {"name": "Divine Storm", "tip": "Crusader Strike now causes Divine Storm which unleashes a whirl of holy hammers, dealing 20 Magical damage (+100% of Strength) (+100% of Intelligence) (+100% of Mastery) to all nearby enemies.\n\nWhile in Protection or Holy Specialziations, the damage dealt will be reduced by 50%, but Righteous Fury will be applied on enemies hit.\n\nThe Paladin needs to have the Righteous Fury ability for its debuff to be applied.", "ret": 197.0, "prot": 171.1}, {"name": "Crusade", "tip": "Each attack grants you 2% Haste, up to a maximum of 20%. This bonus resets upon leaving combat.", "ret": 170.9, "prot": 165.1}, {"name": "Divine Knowledge", "tip": "Regenerates mana equal to 3% of Intelligence each second grants an additional bonus based on current Specialization:\n\nRetribution: Increases the damage of Magical Type effects by 0,3% per point of Intelligence.\n\nProtection & Holy: Every 3 points of Intelligence grant you 1% Healing Power.", "ret": 165.2, "prot": 150.6}, {"name": "Hammer of Justice", "tip": "Replaces Righteous Fury with Hammer of Justice which deals 60 Magical damage (+175% of Strength) and Stuns the target for 5 seconds. The damage dealt will be increased by 1% per point of Intelligence. Whenever Blessed Hammer deals damage, the remaining cooldown of this ability gets reduced by 0,1 seconds. Has 18 seconds cooldown.", "ret": 152.4, "prot": 149.2}, {"name": "Zeal", "tip": "Each spellcast increases the Attack Speed of your next 2 attacks within 4 seconds by 80%.", "ret": 167.0, "prot": 163.9}, {"name": "Hammer Mastery", "tip": "Damage dealt by Blessed Hammer grants you 2 Mastery, up to a maximum of 30. This bonus resets upon leaving combat.", "ret": 161.9, "prot": 150.6}];
const GLYPHS: Entry[] = [{"name": "Animosity", "tip": "Offensive Glyph\nGrants you 12% Critical Strike chance and increases the damage dealt by Critical Strikes by 15%.", "ret": 158.0, "prot": 152.6}, {"name": "Arc Striking", "tip": "Utility Glyph\nEach of your attacks reduces the remaining cooldown of your Q ability by 8% plus additional 0,25 seconds. Your Q spellcasts refund 40% of their mana cost.", "ret": 155.9, "prot": 150.6}, {"name": "Battle Frenzy", "tip": "Offensive Glyph\nGives your attacks 18% chance to grant you 32% Attack Speed for 5 seconds. Battle Frenzy must wear off before occuring again.", "ret": 155.9, "prot": 150.6}, {"name": "Blood Violence", "tip": "Offensive Glyph\nDealing damage from any source has 3% chance to cause the enemy flesh to explode, dealing 20 Attrition damage (+160% of Primary Attribute).", "ret": 155.9, "prot": 150.6}, {"name": "Fortune", "tip": "Utility Glyph\nIncreases your Luck by additional 15%.", "ret": 155.9, "prot": 150.6}, {"name": "Fortitude", "tip": "Utility Glyph\nBoosts your Primary Attribute by 4 and additional 2 per Hero Level.", "ret": 192.7, "prot": 186.0}, {"name": "Glass Cannon", "tip": "Offensive Glyph\nMultiplicatively increases damage dealt from all sources by 15%, but all of your units take 10% more damage.", "ret": 179.3, "prot": 173.2}, {"name": "Hellfire", "tip": "Offensive Glyph\nDeals 3 damage and additional amount equal to 3 times your hero level to all enemy units within 400 range every 1,25 seconds. Damage dealt is modified based on the amount of targets hit:\n\n• 1 enemy: 200% damage\n• 2-3 enemies: 100% damage\n• 4+ enemies: 50% damage", "ret": 155.9, "prot": 150.6}, {"name": "Mindhaste", "tip": "Utility Glyph\nIncreases your Haste by 7% and reduces the cooldown of all abilities by 0,2 seconds.", "ret": 170.9, "prot": 168.1}, {"name": "Supremacy", "tip": "Utility Glyph\nIncreases your Mastery by 20.", "ret": 160.5, "prot": 150.6}, {"name": "Thunder", "tip": "Offensive Glyph\nYour spellcasts have 18% chance to call down lightnings that deal 35 (+200% of Primary Attribute) to enemy units within 600 range.", "ret": 155.9, "prot": 150.6}, {"name": "Unsealed Power", "tip": "Offensive Glyph\nIncreases the damage dealt by Magical and Physical Type effects by 18%.", "ret": 184.0, "prot": 177.7}];

function ranksFor(spec: SpecId, pool: PoolId): string[] {
  return Object.keys(RUNS)
    .filter((id) => id.startsWith(`${spec}|${pool}|`))
    .sort((a, b) => Number(a.split("|")[2]) - Number(b.split("|")[2]));
}

function GameText({ text }: { text: string }) {
  return (
    <Text size="small" style={{ whiteSpace: "pre-wrap" }}>
      {text}
    </Text>
  );
}

export default function PaladinSims() {
  const [spec, setSpec] = useCanvasState<SpecId>("pala-fight-spec", "retribution");
  const [pool, setPool] = useCanvasState<PoolId>("pala-fight-pool", "mixed");
  const [rank, setRank] = useCanvasState<string>("pala-fight-rank", "1");
  const chosenSpec: SpecId = spec === "protection" ? "protection" : "retribution";
  const available = POOLS.filter(([id]) => ranksFor(chosenSpec, id).length > 0);
  const chosenPool: PoolId = available.some(([id]) => id === pool) ? pool : "mixed";
  const ranks = ranksFor(chosenSpec, chosenPool);
  const chosenRank = ranks.some((id) => id.endsWith(`|${rank}`)) ? rank : "1";
  const run = RUNS[`${chosenSpec}|${chosenPool}|${chosenRank}`];
  const specTitle = chosenSpec === "retribution" ? "Retribution" : "Protection";
  const [catalog, setCatalog] = useCanvasState<"picked" | "all">("pala-fight-catalog", "picked");
  const pickedTalents = (run.stats.find((row) => row[0] === "Таланты")?.[1] ?? "").split(", ").filter(Boolean);
  const pickedGlyphs = (run.stats.find((row) => row[0] === "Глифы")?.[1] ?? "").split(", ").filter(Boolean);
  const dpsOf = (entry: Entry) => (chosenSpec === "retribution" ? entry.ret : entry.prot);
  const talentRows = (catalog === "picked" ? TALENTS.filter((entry) => pickedTalents.includes(entry.name)) : TALENTS)
    .slice()
    .sort((a, b) => dpsOf(b) - dpsOf(a));
  const glyphRows = (catalog === "picked" ? GLYPHS.filter((entry) => pickedGlyphs.includes(entry.name)) : GLYPHS)
    .slice()
    .sort((a, b) => dpsOf(b) - dpsOf(a));

  return (
    <Stack gap={20}>
      <Stack gap={6}>
        <H1>{specTitle} Paladin, 5 целей</H1>
        <Text tone="secondary">
          {chosenSpec === "retribution"
            ? "Sunken City v2.5.2a · уровень 6 · 30 секунд · набор топ-89 и Mind Amplifier · eseid-main 0–431 803 665, ошибок 0 · eseid-notebook 431 803 666–591 511 871, ошибок 2 497 435"
            : "Sunken City v2.5.2a · уровень 6 · 30 секунд · eseid-main · чанки 0–612 734 667 · ошибок в файле 0"}
        </Text>
      </Stack>

      <Row gap={8} wrap>
        <Pill active={chosenSpec === "retribution"} onClick={() => setSpec("retribution")}>Retribution</Pill>
        <Pill active={chosenSpec === "protection"} onClick={() => setSpec("protection")}>Protection</Pill>
      </Row>
      <Row gap={8} wrap>
        <Pill active={true}>5 целей</Pill>
      </Row>
      <Row gap={8} wrap>
        {available.map(([id, label]) => (
          <Pill active={chosenPool === id} onClick={() => setPool(id)}>{label}</Pill>
        ))}
      </Row>
      {ranks.length > 1 ? (
        <Row gap={8} wrap>
          {ranks.map((id) => {
            const place = id.split("|")[2];
            return (
              <Pill active={chosenRank === place} onClick={() => setRank(place)}>
                {`${place} · ${RUNS[id].dps}`}
              </Pill>
            );
          })}
        </Row>
      ) : null}

      <Grid columns={5} gap={16}>
        <Stat value={run.dps} label="DPS" tone="success" />
        <Stat value={run.total} label="Урон за 30 с" />
        <Stat value={run.crit} label="Крит" />
        <Stat value={run.strength} label="Сила" />
        <Stat value={run.manaLeft} label="Мана в конце" />
      </Grid>
      {run.farm !== run.dps ? (
        <Text size="small" tone="tertiary">
          В файле фермы у этой связки {run.farm} DPS. Разбор ниже — текущий сим.
        </Text>
      ) : null}

      <H2>Урон по источникам</H2>
      <BarChart
        horizontal
        height={220}
        categories={run.sources.map((row) => row[0])}
        series={[{ name: "DPS", data: run.sources.map((row) => row[1]) }]}
        valueSuffix=" DPS"
        showValues
      />
      <Text size="small" tone="tertiary">
        Ось категорий: источник урона. Ось значений: урон в секунду за 30 с. Броня манекена 15. Ранги умений 1. Пять целей стоят в одной точке на дистанции взмаха 80: молот бьёт их вместе, только пока спираль накрывает эту точку, затем та же пара ждёт 0,85 с.
      </Text>

      <Grid columns={2} gap={20}>
        <Stack gap={8}>
          <H3>Порядок кнопок</H3>
          <Table
            headers={["Секунда", "Способность"]}
            columnAlign={["right", "left"]}
            rows={run.actions}
            striped
          />
          <Text size="small" tone="tertiary">
            Каст 0,15 с до эффекта, затем ещё 0,30 с герой занят. В таблице все нажатия за 30 с. Чанк {run.chunk}.
          </Text>
        </Stack>
        <Stack gap={8}>
          <H3>Характеристики в бою</H3>
          <Table headers={["Параметр", "Значение"]} rows={run.stats} />
        </Stack>
      </Grid>

      <Divider />

      <H2>Предметы в связке</H2>
      <Text tone="secondary">{run.label}. {specTitle}. 5 целей.</Text>
      <Table
        headers={["Предмет", "Источник", "Описание из игры"]}
        rows={run.items.map(([name, sourceName, tip]) => [name, sourceName, <GameText text={tip} />])}
        striped
      />

      <Row gap={8} align="center">
        <H2>Таланты и глифы</H2>
        <Pill active={catalog === "picked"} onClick={() => setCatalog("picked")}>В связке</Pill>
        <Pill active={catalog === "all"} onClick={() => setCatalog("all")}>Все прогнанные</Pill>
      </Row>
      <Text size="small" tone="tertiary">
        Порядок — DPS выбранной специализации: один талант или один глиф, пустой инвентарь, 5 целей. В прогоне 8 талантов набора и 12 глифов.
      </Text>
      <H3>Таланты</H3>
      <Table
        headers={["Талант", specTitle, "Описание из игры"]}
        columnAlign={["left", "right", "left"]}
        rows={talentRows.map((entry) => [entry.name, dpsOf(entry).toFixed(1), <GameText text={entry.tip} />])}
        striped
        rowTone={talentRows.map((entry) => (pickedTalents.includes(entry.name) ? "success" : undefined))}
      />
      <H3>Глифы</H3>
      <Table
        headers={["Глиф", specTitle, "Описание из игры"]}
        columnAlign={["left", "right", "left"]}
        rows={glyphRows.map((entry) => [entry.name, dpsOf(entry).toFixed(1), <GameText text={entry.tip} />])}
        striped
        rowTone={glyphRows.map((entry) => (pickedGlyphs.includes(entry.name) ? "success" : undefined))}
      />
    </Stack>
  );
}
